CREATE TABLE audit_events(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,actor_type VARCHAR(30),actor_id VARCHAR(100),action VARCHAR(100) NOT NULL,resource_type VARCHAR(100) NOT NULL,resource_id VARCHAR(100),outcome VARCHAR(20) NOT NULL,ip_address VARCHAR(64),user_agent VARCHAR(500),correlation_id VARCHAR(100),source_service VARCHAR(100),details TEXT,occurred_at TIMESTAMP(6) NOT NULL,recorded_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_audit_tenant_occurred ON audit_events(tenant_id,occurred_at);CREATE INDEX idx_audit_resource ON audit_events(resource_type,resource_id);CREATE INDEX idx_audit_actor ON audit_events(actor_type,actor_id);CREATE INDEX idx_audit_correlation ON audit_events(correlation_id);
